function NewChapter2DVo:FillVo(row)
    base.FillVo(self, row)
    self.id = parse_number(row, "id", 0)
    self.nextId = parse_number(row, "nextId", 0)
    self.sameTime = parse_string(row, "sameTime", "")
    if not string.isEmpty(self.sameTime) then
        self.sameTime = parse_strings(self.sameTime, ";")
    end
    self.type = parse_number(row, "type", 0)
    self.characterName = parse_localizeText(row, "characterName", "")
    self.feCharacterName = self:ParseChapterLocalizeText(row, "feCharacterName", true,self.characterName)
    self.desc = parse_localizeText(row, "desc", "")
    self.feDesc = self:ParseChapterLocalizeText(row, "fedesc", true,self.desc)
    self.sceneType = parse_number(row, "sceneType", NewChapterConstants.BgType.Normal)
    local ChapterUtils = import('Game.Chapter.ChapterUtils')
    ---@type PlayerComponent
    local playerComp = ChapterUtils.GetPlayerComp()
    if self.sceneType == NewChapterConstants.BgType.BgMovie then
        self.sceneId = parse_string(row, "sceneId")
    else
        if self.type == NewChapterConstants.NewType.StartAnimation then
            self.sceneId = parse_string(row, "sceneId")
        elseif self.type == NewChapterConstants.NewType.LoadingFirst or self.type == NewChapterConstants.NewType.LoadingSecond  then
            self.sceneId = string.split(parse_string(row, "sceneId"),":")[2]
        else
            local sceneId = ParseUtils.ParsePathName(row, "sceneId")
            sceneId = ChapterUtils.ReplaceStr(sceneId, "#gender", playerComp.playerDojo.gender)
            self.sceneId = sceneId
        end
    end

    local sceneBgId =  ParseUtils.ParsePathName(row, "sceneBgId")
    sceneBgId = ChapterUtils.ReplaceStr(sceneBgId, "#gender", playerComp.playerDojo.gender)
    self.sceneBgId = sceneBgId

    self.flashBackTime = parse_number(row, "flashBackTime", 0)
    self.screenAnim = parse_number(row, "screenAnim", 0)
    if self.screenAnim == NewChapterConstants.ScreenEffect.FullBlackFadeOut then
        self.screenTime = 1
    else
        self.screenTime = parse_number(row, "screenTime", 0)
    end

    --self.characterRes = parse_string(row, "characterRes", "")
    --self.Is2D = not string.isEmpty(self.characterRes)
    self.characterRes = parse_string(row, "characterRes", "")
    if not string.isEmpty(self.characterRes) then
        self.characterRes = parse_strings(self.characterRes, ";")
    end

    --self.characterId = parse_strings(row, "characterId", 0)
    self:ParseNumbers(row, "characterId")

    self:ParseNumbers(row, "effectRootId")

    --self.position = parse_number(row, "position", 0)
    self:ParseNumbers(row,"position")
    
    --self.rotation = parse_number(row, "rotation", 0)
    self:ParseNumbers(row,"rotation")
    
    --self.effect = parse_number(row, "effect", 0)
    self:ParseNumbers(row,"effect")

    --self.enter = parse_number(row, "enter", 0)
    self:ParseNumbers(row,"enter")
    
    --self.action = parse_number(row, "action", 0)
    self:ParseNumbers(row,"action")
    
    --self.loop = parse_number(row, "loop", 0) == 1
    self:ParseNumbers(row,"loop")
    for i = 1, #self.loop do
        self.loop[i] = self.loop[i] == 1
    end

    --self.eyes = parse_string(row, "eyes", "")
    self:ParseNumbers(row,"eyes")
    
    --self.faceId = parse_number(row, "faceId", 0)
    self:ParseNumbers(row,"faceId")

    self:ParseNumbers(row,"EntryTip")
    
    --self.dialogStyle = parse_number(row, "dialogStyle", 0)
    --self.dialogPos = parse_number(row, "dialogPos", 0)
    self.avatar = ParseUtils.ParsePathName(row, "avatar")
    self.exist = parse_number(row, "exist", 0)
    self.music = parse_string(row, "music", "")
    --if not string.isEmpty(self.music) then
    --    self.music = parse_strings(self.music, ";")
    --end
    self.sound = parse_string(row, "sound", "")
    --if not string.isEmpty(self.sound) then
    --    self.sound = parse_strings(self.sound, ";")
    --end
    self.soundDelay = parse_number(row, "soundtime", 0)
    
    self.loopSE = parse_string(row, "loopSE", "")
    --if not string.isEmpty(self.loopSE) then
    --    self.loopSE = parse_strings(self.loopSE, ";")
    --end
    self.voice = parse_string(row, "voice", "")
    --if not string.isEmpty(self.voice) then
    --    self.voice = parse_strings(self.voice, ";")
    --end
    self.feVoice = parse_string(row, "fevoice", "")
    self.speaker = parse_number(row, "speaker", 0)
    self.displayItem = ParseUtils.ParsePathName(row, "displayItem")
    self.itemAction = parse_number(row, "itemAction", 0)
    self.option = parse_localizeText(row, "option", "")
    self.feOption = self:ParseChapterLocalizeText(row, "feOption", true, self.option)
    if not string.isEmpty(self.option) then
        self.option = parse_strings(self.option, ";")
    end

    if not string.isEmpty(self.feOption) then
        self.feOption = parse_strings(self.feOption, ";")
