function NewChapter2DVo:SetupPath(is2D)
    self.Is2D = is2D == 1
    --printInfo("is 2d %d %s",is2D, tostring(self.Is2D))
    local ext = self.Is2D and AtlasExt or ModelExt
    local path = self.Is2D and Path2D or Path3D

    if not string.isEmpty(self.characterId) then
        self.characterPath = {}
        self.animatorPath = {}
        for i = 1, #self.characterId do
            --lobby模型功能关闭 2022.8.29 by zhao
            --if GoodsUtils.GetIdType(self.characterId[i]) == Constants.IDType.CardSkin then
            --    local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(self.characterId[i])
            --    table.insert(self.characterPath, string.format("Arts/Prefab_lobby/%s.prefab", skinVo.lobbyMode))
            --    if not self.Is2D then
            --        table.insert(self.animatorPath, "")
            --    end
            --    self.characterId[i] = skinVo.roleId
            --else
            --    local tPath = string.format(path, self.characterId[i])
            --    table.insert(self.characterPath, ParseUtils.ParsePathNameByData(tPath, ext))
            --    if not self.Is2D then
            --        table.insert(self.animatorPath, string.format(AnimatorPath, self.characterId[i]))
            --    end
            --end
            local tPath = string.format(path, self.characterId[i])
            table.insert(self.characterPath, ParseUtils.ParsePathNameByData(tPath, ext))
            if not self.Is2D then
                table.insert(self.animatorPath, string.format(AnimatorPath, self.characterId[i]))
            end
        end
    else
        self.characterPath = ""
        self.animatorPath = ""
    end
end

function NewChapter2DVo:ParseNumbers(row, key)
    self[key] = parse_string(row, key, "")
    if not string.isEmpty(self[key]) then
        self[key] = parse_strings(self[key], ";")
        for i = 1, #self[key] do
            self[key][i] = checkNumber(self[key][i])
        end
    end
end

---parse_localizeText
---lua层的字符串信息
---@param row TableML.TableFileRow
---@param header_name string
---@param isLinefeed boolean @ 是否解析换行，需要解析的话传一个true
---@return string
function NewChapter2DVo:ParseChapterLocalizeText(row, header_name, isLinefeed, defStr)
    local ret = ParseUtils.ParseChapterLocalizeText(row, header_name, defStr)
    if not isNull(isLinefeed) then
        ret = string.gsub(tostring(ret), "\\n", "\n")
    end
    return ret
end

return NewChapter2DVo
